  if (elements.nextGoalLabel) elements.nextGoalLabel.textContent = next ? `${goalDateValue(next)} — ${next.discipline}: ${next.subject}` : "-";
  if (elements.weekTopDiscipline) elements.weekTopDiscipline.textContent = top ? `${top[0]} (${top[1]})` : "-";
