function ensureGeneratedSvgBrand(svg) {
  const source = String(svg || '');
  if (!source || source.includes('data-generated-brand="Aldus Metas Concurso"')) return source;
  const viewBox = source.match(/viewBox="([\d.-]+) ([\d.-]+) ([\d.-]+) ([\d.-]+)"/);
  const y = Number(viewBox?.[2]) || 0, width = Number(viewBox?.[3]) || 1600;
  return source.replace(/(<svg\b[^>]*>)/, `$1${generatedBrandMarkSvg(Math.max(20, width - 360), y + 25, 320)}`);
}
function rasterizeSvgToPngBlob(svg, options = {}) { return new Promise((resolve, reject) => { const img = new Image(); const url = URL.createObjectURL(new Blob([String(svg || '')], { type: 'image/svg+xml;charset=utf-8' })); img.onload = () => { const canvas = document.createElement('canvas'); canvas.width = options.width || 1600; canvas.height = options.height || Math.max(700, Math.round(canvas.width * img.height / img.width)); const ctx = canvas.getContext('2d'); ctx.fillStyle = options.background || '#fff'; ctx.fillRect(0,0,canvas.width,canvas.height); ctx.drawImage(img,0,0,canvas.width,canvas.height); URL.revokeObjectURL(url); canvas.toBlob(b => b ? resolve(b) : reject(new Error('PNG indisponível')), 'image/png'); }; img.onerror = () => { URL.revokeObjectURL(url); reject(new Error('Não foi possível renderizar a logo.')); }; img.src = url; }); }
