function downloadGeneratedFile(blob, filename) { const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = sanitizeExportFilename(filename); document.body.appendChild(a); a.click(); a.remove(); setTimeout(() => URL.revokeObjectURL(url), 1000); }
async function downloadGeneratedExcel(csv, filename, options = {}) {
  const logoBlob = await rasterizeSvgToPngBlob(generatedBrandLogoSvg(), { width: 600, height: 220 });
  const logoBytes = new Uint8Array(await logoBlob.arrayBuffer());
  const archive = buildBrandedXlsxArchive(generatedCsvRows(csv), logoBytes, options);
  downloadGeneratedFile(new Blob([archive], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' }), filename);
}
async function shareGeneratedFile(blob, filename, mimeType) { const file = new File([blob], filename, { type: mimeType }); if (navigator.canShare?.({ files: [file] })) return navigator.share({ files: [file], title: filename }); downloadGeneratedFile(blob, filename); }
function buildPerformancePrintHtml(payload) {
  const summary=payload.summary||{}, questions=payload.questions||{}, period=payload.filters?.periodLabel||payload.filters?.mode||'Período selecionado';
  const discipline=payload.filters?.discipline&&payload.filters.discipline!=='all'?payload.filters.discipline:'Todas as disciplinas';
  const planned=(payload.plannedVsActual||[]).reduce((a,r)=>({planned:a.planned+(Number(r.plannedMinutes)||0),actual:a.actual+(Number(r.actualMinutes)||0)}),{planned:0,actual:0});
  const metrics=[['Tempo estudado',summary.timeLabel||formatExportDuration(summary.minutes||0),'blue'],['Dias ativos',summary.activeDays||0,'purple'],['Sessões',summary.sessions||0,'cyan'],['Questões',summary.questions||0,'amber'],['Líquido Cebraspe',summary.cebraspeNet??questions.cebraspeNet??0,'green'],['Metas concluídas',summary.goalsCompleted||0,'pink']];
  const rows=(payload.disciplines||[]).slice().sort((a,b)=>(Number(b.minutes)||0)-(Number(a.minutes)||0));
  return `<article id="performancePrintableReport" class="performance-print-report"><header class="performance-print-hero">${generatedBrandPrintHtml()}<p>ANÁLISE ESTRATÉGICA</p><h1>Relatório de desempenho</h1><div>Período: <strong>${escapeHTML(period)}</strong> • Disciplina: <strong>${escapeHTML(discipline)}</strong></div><small>Verde = avanço • Azul = progresso • Amarelo = atenção • Cinza = sem dados</small></header><section><h2>Resumo geral</h2><p class="performance-print-explainer">Comece por estes indicadores para entender o volume e a constância do período.</p><div class="performance-print-metrics">${metrics.map(([l,v,t])=>`<div class="metric ${t}"><span>${escapeHTML(l)}</span><strong>${escapeHTML(String(v))}</strong></div>`).join('')}</div></section><section><h2>Questões e líquido Cebraspe</h2><div class="performance-print-question-grid"><div class="correct"><strong>${questions.correct||0}</strong><span>Acertos</span></div><div class="wrong"><strong>${questions.wrong||0}</strong><span>Erros</span></div><div class="blank"><strong>${questions.blank||0}</strong><span>Brancos</span></div><div class="net"><strong>${(questions.cebraspeNet||0)>0?'+':''}${questions.cebraspeNet||0}</strong><span>Líquido</span></div></div><p class="performance-print-tip"><strong>Como interpretar:</strong> ${escapeHTML(performanceReadingText({accuracy:questions.accuracyPct,questions:(questions.correct||0)+(questions.wrong||0)+(questions.blank||0),net:questions.cebraspeNet}))}</p></section><section><h2>Desempenho por disciplina</h2><p class="performance-print-explainer">A classificação é orientativa. Com menos de 20 questões, trate o resultado apenas como sinal inicial.</p><table><thead><tr><th>Disciplina</th><th>Tempo</th><th>Questões</th><th>Acerto</th><th>Líquido</th><th>Leitura</th></tr></thead><tbody>${rows.length?rows.map(d=>`<tr><td><strong>${escapeHTML(d.discipline||'Sem disciplina')}</strong></td><td>${escapeHTML(formatExportDuration(d.minutes||0))}</td><td>${d.questions||0}</td><td>${d.accuracyPct||0}%</td><td>${(d.net||0)>0?'+':''}${d.net||0}</td><td>${escapeHTML(performanceReadingText({accuracy:d.accuracyPct,questions:d.questions,net:d.net}))}</td></tr>`).join(''):'<tr><td colspan="6">Sem dados por disciplina.</td></tr>'}</tbody></table></section><section><h2>Planejado x realizado</h2><div class="performance-print-plan"><div><span>Planejado</span><strong>${formatExportDuration(planned.planned)}</strong></div><div><span>Realizado</span><strong>${formatExportDuration(planned.actual)}</strong></div><div><span>Situação</span><strong>${planned.planned?performanceStatus(planned.actual,planned.planned).label:'Sem planejamento'}</strong></div></div></section><section><h2>Próximos passos</h2><ul>${((payload.insights||[]).slice(0,6).length?(payload.insights||[]).slice(0,6):['Continue registrando estudos e questões para ampliar a precisão da análise.']).map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></section><footer>Aldus Metas Concurso • Gerado em ${escapeHTML(new Date(payload.generatedAt||new Date().toISOString()).toLocaleString('pt-BR'))} • Dados locais da aba Desempenho</footer></article>`;
}
function cleanupPerformancePrintView() { document.body.classList.remove('performance-print-mode'); document.getElementById('performancePrintableReport')?.remove(); }
function openPerformancePrintView(payload) { cleanupPerformancePrintView(); document.body.insertAdjacentHTML('beforeend', buildPerformancePrintHtml(payload)); document.body.classList.add('performance-print-mode'); window.__performancePrintPayload = payload; window.addEventListener('afterprint', cleanupPerformancePrintView, { once:true }); setTimeout(() => window.print(), 80); }
function exportChartToPng(chartDefinition, metadata) { const svg = buildChartSvg(chartDefinition.type, chartDefinition.data, metadata); return svgToPngBlob(svg, { width: 2400, height: 1575 }).then(blob => { downloadGeneratedFile(blob, `${metadata.filename}.png`); return blob; }); }
async function exportFullReportPngFiles(payload, filenameBase) {
  const svg = buildFullPerformanceReportSvg(payload, { period: payload.filters?.periodLabel || payload.filters?.mode || 'Período selecionado' });
  const sourceHeight = Number(svg.match(/viewBox="0 0 1600 (\d+)/)?.[1]) || 720;
  const safeSourceHeight = 3200;
  const parts = Math.max(1, Math.ceil(sourceHeight / safeSourceHeight));
  const blobs = [];
  for (let i = 0; i < parts; i += 1) {
    const y = i * safeSourceHeight;
    const h = Math.min(safeSourceHeight, sourceHeight - y);
    const partSvg = parts === 1 ? svg : svg.replace(/viewBox="0 0 1600 \d+"/, `viewBox="0 ${y} 1600 ${h}"`).replace(/<title>Relatório de Desempenho<\/title>/, `<title>Relatório de Desempenho - parte ${i + 1}<\/title>`);
    const blob = await svgToPngBlob(partSvg, { width: 2400, height: Math.round(h * 1.5) });
    downloadGeneratedFile(blob, parts === 1 ? `${filenameBase}.png` : `${filenameBase}-parte-${i + 1}-de-${parts}.png`);
    blobs.push(blob);
  }
  return blobs;
}
async function exportFullReportPng(payload, filenameBase) { const files = await exportFullReportPngFiles(payload, filenameBase); return files[0]; }
